import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Familiarity y práctica","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/characters/familiarity.md","filePath":"es/guide/characters/familiarity.md"}'),r={name:"es/guide/characters/familiarity.md"};function d(o,a,s,c,l,m){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="familiarity-and-practice" tabindex="-1">Familiarity y práctica <a class="header-anchor" href="#familiarity-and-practice" aria-label="Enlace permanente a &quot;Familiarity y práctica&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto para niveles compartidos · Experimental para modificadores marciales y retención · No implementado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Aprender conserva conocimiento; practicar mejora la ejecución mediante Learned, Practiced y Mastered.</li><li>La retención marcial Experimental cuenta días de juego activos, no ausencias de calendario.</li><li>Opciones preparadas y fluidez son distintas; los modificadores marciales no asignan valores a hechizos.</li></ul><p>Aprender da conocimiento permanente; practicar mejora la fluidez. El tiempo ausente no borra técnicas.</p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nivel de SA marcial</th><th>Stamina / recuperación</th><th>Precisión</th><th>Ventana defensiva</th></tr></thead><tbody><tr><td>Learned</td><td>+5% / +5%</td><td>−2 pp</td><td>−5%</td></tr><tr><td>Practiced</td><td>Normal</td><td>Normal</td><td>Normal</td></tr><tr><td>Mastered</td><td>−3% / −3%</td><td>+1 pp</td><td>+5%</td></tr></tbody></table><p>Sin bonificación de daño bruto. Estos valores marciales de estado Experimental no asignan costes ni tiempos de lanzamiento de hechizos; los hechizos solo comparten los nombres de niveles. Las básicas siguen neutrales.</p><h2 id="maintenance-test" tabindex="-1">Prueba de mantenimiento <a class="header-anchor" href="#maintenance-test" aria-label="Enlace permanente a &quot;Prueba de mantenimiento&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Conservar</th><th>Usos en el mundo</th><th>O entrenamiento</th></tr></thead><tbody><tr><td>Mastered</td><td>20</td><td>5 repeticiones</td></tr><tr><td>Practiced</td><td>9</td><td>3 repeticiones</td></tr><tr><td>Learned</td><td>Ninguno</td><td>Mínimo permanente</td></tr></tbody></table><ul><li>Los recuentos usan los últimos 7 días activos, no los días de calendario de ausencia.</li><li>Día activo de prueba: al menos 10 minutos de juego no inactivo en una fecha UTC.</li><li>Solo cuentan usos significativos y válidos; las reglas de ejercicios y abuso todavía necesitan pruebas.</li><li>Debe cumplirse el umbral de mundo o el de entrenamiento; mezclarlos todavía no tiene tasa de conversión.</li><li>La evaluación comienza tras 7 días activos desde aprender/subir de nivel y baja como máximo un nivel por comprobación de día activo.</li><li>Son reglas de retención. Cómo subir de nivel sigue sin resolverse.</li></ul><h2 id="training-and-preparation" tabindex="-1">Entrenamiento y preparación <a class="header-anchor" href="#training-and-preparation" aria-label="Enlace permanente a &quot;Entrenamiento y preparación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Apoyo</th><th>Propósito</th></tr></thead><tbody><tr><td>Maniquíes / campos de tiro / salas de práctica</td><td>Mantener fluidez eficientemente</td></tr><tr><td>Carpentry / Tinkering / Inscription</td><td>Equipo y materiales candidatos de instalaciones</td></tr><tr><td>5 ranuras de SA preparadas</td><td>Opciones listas, no todas las técnicas conocidas</td></tr></tbody></table><p>Las instalaciones no pretenden ser el mejor método repetitivo para subir habilidades principales ni saltarse el descubrimiento. Las técnicas preparadas no reciben protección especial frente al decaimiento en esta primera prueba.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un espadachín ausente vuelve con los mismos conocimientos y sin nuevos días activos contabilizados. Al continuar jugando, la fluidez descuidada puede bajar hacia Learned, nunca Unknown.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Special Attacks</a> · <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria de hechizos</a> · <a href="/Syrolands-Public/es/game-design/characters/familiarity.html">Diseño completo</a> · <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html#maintenance-test">Reglas exactas de prueba</a></p>',18)])])}const h=e(r,[["render",d]]);export{u as __pageData,h as default};
